export function getPlanDisplayName({
	planId,
	plan
}: {
	planId: string | null | undefined
	plan: OrganizationPlan
}): string {
	// stripeProductId? ex: usage_pro_20
	// revenueCatProductId? ex: usage_pro_20_monthly
	if (planId) {
		const displayName =
			stripeUsagePlanDisplayNames[planId] ||
			revenueCatUsagePlanDisplayNames[planId]
		if (displayName) {
			return displayName
		}
	}

	return planDisplayNames[plan] || 'Unknown plan'
}

export const isPaidPlan = (plan: OrganizationPlan) => {
	return ![OrganizationPlan.FREE, OrganizationPlan.FREE_USAGE].includes(plan)
}
